"""Editorial answers, based exclusively on the completed audit artifacts."""
ENTRIES=[]
def add(ids,title,status,answer,refs=(),quote=None,page=None):
    ENTRIES.append(dict(ids=ids.split(),title=title,status=status,answer=answer,refs=list(refs),quote=quote,page=page))

add('X01','Abrangência de 100% do BWeb','Confere com delimitação',
'O conjunto conferido contém BWeb das 27 unidades federativas e do exterior, com 499.205 seções representadas. A base de boletins tem 499.207 seções: duas seções do exterior, ambas sem votos, não aparecem no BWeb. Não houve perda de votos por essa diferença. A cobertura obtida nesta auditoria não prova, por si, quais arquivos o autor dos prints efetivamente processou.',('R1','R2'),
'Abrangência: 100% dos Boletins de Urna (BWeb) das 28 Unidades da Federação',1)
add('A04','Quantidade de unidades abrangidas','Número de recortes confere; nomenclatura precisa de ajuste',
'Foram abrangidos 28 recortes de dados. Eles correspondem a 27 unidades federativas, incluindo o Distrito Federal, mais o exterior, identificado como ZZ. Portanto, o número 28 corresponde à quantidade de recortes; o exterior não é uma 28ª unidade da Federação.',('R1','R2'))
add('A01 A01V','499.205 seções e 128.236.074 votos','Os dois números conferem',
'As 499.205 seções conferem para o BWeb. O comparecimento presidencial total foi de 128.236.074, incluindo votos válidos, brancos e nulos. Destes, 124.082.273 foram válidos, 1.430.496 brancos e 2.723.305 nulos. As duas seções adicionais dos BUs não tiveram votos e não mudam esse total.',('R1','R2','R3'))
add('A05','Data declarada da análise','Não foi possível verificar a data de execução',
'O print traz a data de 28 de outubro de 2026. Não foram fornecidos registros de execução ou arquivos do autor com uma cronologia verificável que permitisse confirmar que o processamento foi realizado nessa data. A presença da data no documento é verificável; a data efetiva de sua produção permanece não confirmada.',('R0',))
add('X02','Origem oficial dos dados','Compatível com as fontes conferidas',
'Os arquivos usados nesta auditoria foram associados aos catálogos e endereços oficiais do TSE. Os totais citados no original são, em grande parte, reproduzíveis nesses arquivos. Isso confirma a compatibilidade dos números com a fonte oficial, mas não permite comprovar o histórico de obtenção dos arquivos particulares do autor.',('R1','R2','R3','D13'),
'Fonte: Repositório oficial de Dados Abertos do TSE',1)

add('X03','Proclamação na noite de 25 de outubro','Horário exato não verificado',
'Não foi obtido, no material reunido, um registro primário com a marca temporal exata da proclamação. Por isso, esta resposta não fixa um horário de proclamação nem o usa para validar a alegação posterior de uma decisão tomada sete minutos depois. Para isso seriam necessários a ata ou o registro da sessão e o ato assinado a comparar.',('R0','D06'),
'os resultados gerais foram totalizados e proclamados pelo Tribunal Superior Eleitoral na noite de domingo, 25 de outubro.',2)
add('F01','Liberação do BWeb somente em 28 de outubro','Não foi possível confirmar a primeira disponibilidade',
'Não há histórico completo de acesso aos arquivos por URL que permita datar sua primeira disponibilização. Data de geração, data do catálogo e Last-Modified não equivalem à primeira publicação. Assim, não foi possível confirmar nem refutar, de forma fechada, a manhã de 28 de outubro como primeiro acesso ao BWeb.',('D12','D13'))
add('F02','72 horas sem acesso aos dados primários','Não foi possível verificar o período integral',
'Não foi obtida uma cronologia contínua e independente para todos os produtos: BWeb, boletins, RDVs e logs. Há referências a análise de logs em 26 de outubro, o que precisa ser considerado, mas isso não estabelece a disponibilidade de cada pacote BWeb. A alegação geral de 72 horas sem todos os dados permanece inconclusiva.',('D12','D13'))
add('X09','Reconhecimento diplomático e medidas contra a oposição durante o intervalo','Não foi possível verificar o nexo proposto',
'O trecho reúne acontecimentos diferentes e lhes atribui uma função política comum, sem apresentar uma sequência documental completa. Não foi possível confirmar essa relação. As afirmações específicas sobre decisões, Polícia Federal e proteção diplomática recebem respostas próprias nas páginas 4 e 5 deste documento. A ausência de documentos suficientes não é tratada como demonstração de que os acontecimentos não ocorreram.',('D06','D07','D10','D11'),
'enquanto a máquina estatal acelerava o reconhecimento diplomático internacional, impunha medidas de exceção contra a oposição e consolidava o fato político consumado.',2)
add('A02 A02V','Repetição dos totais nacionais','Os números conferem',
'Os valores de 499.205 seções no BWeb e 128.236.074 votos/comparecimentos presidenciais são os mesmos conferidos na página 1. A auditoria reconstruiu os totais em 499.207 BUs, dos quais dois não têm votos. Essa reprodução não permite verificar a afirmação de que a equipe do documento original processou pessoalmente toda a base.',('R1','R2','R3'))
add('B01','52,39% para Flávio nas seções encerradas até 17h','Confere no recorte local por minuto',
'O valor calculado foi de 52,394947%, que arredonda para 52,39%. A reprodução usa os relógios locais e inclui o minuto 17h00 inteiro, até 17:00:59. São os votos totais das seções desse grupo, não os votos individuais registrados até 17h. Na alternativa já calculada em horário de Brasília, restrita ao território nacional, o resultado foi 50,991691%. A mudança envolve tanto o relógio quanto a população, pois o exterior fica fora dessa alternativa.',('R1','R4'))
add('B02','Vantagem de quase 1,8 milhão de votos','Valor exato disponível; expressão aproximada',
'A vantagem no recorte local reproduzido foi de 1.747.639 votos para Flávio. Esse é o número exato a usar em lugar da expressão “quase 1,8 milhão”, cuja tolerância não foi definida no original. Na alternativa doméstica em Brasília, a vantagem foi de 607.102. Nenhum dos dois valores representa uma contagem dos votos individuais recebidos até as 17h.',('R1','R4'))
add('B03','Mais de 6,1 milhões de vantagem nas seções posteriores','Confere no recorte local por minuto',
'A vantagem de Lula no grupo com encerramento local a partir de 17:01:00 foi de 6.177.738 votos, portanto maior que 6,1 milhões. Na alternativa doméstica em Brasília, o valor foi de 5.008.636. Esses são saldos de toda a votação das seções agrupadas. Não são quantidades de votos depositados depois das 17h.',('R1','R4'))
add('B04','Resultado fabricado no grupo de encerramento tardio','Não foi possível confirmar fabricação a partir desse recorte',
'O saldo entre grupos de seções é calculável, como mostram os dois pontos anteriores. Ele não identifica quais votos seriam indevidos, nem seu horário individual. Não foi apresentada uma regra de comparação que transforme a diferença entre grupos em uma medida de votos fabricados. A informação disponível, portanto, permite conferir os saldos, mas não confirmar essa conclusão causal.',('R1','R4','D01','D05'))
add('X04','Prorrogação de duas horas e alcance da decisão','Registro documental parcial; efeito por seção não medido',
'Há comunicado oficial sobre o cumprimento da decisão de prorrogação. O conjunto documental reunido não foi suficiente para conferir aqui toda a cadeia de atos, horários de assinatura e alcance de cada decisão. Tampouco permite afirmar que cada seção encerrada depois das 17h foi necessariamente afetada pela prorrogação: encerramento, atendimento de fila e registro de voto são eventos distintos.',('D01','D05'),
'Após a contestação da oposição sobre a prorrogação de duas horas concedida pelo ministro Cristiano Zanin',2)
add('X05','A referência a aproximadamente 34 mil votos após 17h','Total nacional exato não fechado nesta auditoria',
'O levantamento oficial citado informa 34.393 votos após 17h. Nos logs domésticos com contagens e horários reconciliados foram encontrados 33.995 registros de voto computado após esse horário. Essa contagem é parcial: um log está ausente e há seções com restrições temporais ou de reconciliação. Não se deve converter essas lacunas em zero. Também não é correto usar o total de eleitores de seções tardias para refutar o número de votos individuais tardios. A diferença exata com o levantamento oficial permanece sem esclarecimento completo.',('R5','D04'),
'apenas trinta e quatro mil votos teriam sido depositados no período estendido',2)

add('B05S B05T B05P','Encerramento entre 17h01 e 17h15','Os três números conferem no recorte local',
'Foram reproduzidas 339.593 seções, com comparecimento total de 88.071.750 e 53,462837% dos votos válidos para Lula, arredondados para 53,46%. O intervalo aplicado foi de 17:01:00 a 17:15:59. O comparecimento soma todos os eleitores dessas seções, durante todo o dia. Na alternativa doméstica em Brasília, os valores foram 363.428 seções, 93.718.230 comparecimentos e 52,608718% para Lula.',('R1','R4'))
add('B06S B06T B06P','Encerramento entre 17h16 e 18h59','Os três números conferem no recorte local',
'Foram reproduzidas 2.472 seções, com comparecimento total de 674.799 e 57,164826% dos votos válidos para Lula, arredondados para 57,16%. O intervalo aplicado foi de 17:16:00 a 18:59:59. Na alternativa doméstica em Brasília, foram 2.493 seções, 675.182 comparecimentos e 57,135384% para Lula. Novamente, são votos e eleitores de toda a seção, não apenas do intervalo.',('R1','R4'))
add('B07S B07T','Encerramento após 19h','Os totais diferem no corte estrito conferido',
'Para encerramento local estritamente posterior a 19:00:00, o resultado foi de 6.326 seções e 1.853.265 comparecimentos, contra 6.333 e 1.856.306 no original: diferenças de 7 seções e 3.041 comparecimentos. Na alternativa doméstica em Brasília, foram 6.336 seções e 1.856.250 comparecimentos. A saída local também registra 16 seções exatamente às 19:00:00; incluí-las produz 6.342, e não 6.333. Assim, a diferença nacional não se resolve apenas trocando >19h por >=19h de maneira uniforme. O original não explicita suficientemente fronteiras em segundos, tratamento do exterior e versão dos dados para resolver essa diferença. Ela é registrada como diferença de reprodução no recorte adotado, não como indício automático de alteração de votos.',('R1','R4'))
add('B08','Mais de 2,5 milhões em seções que encerraram mais tarde','A quantidade confere para os grupos de seções',
'A soma dos comparecimentos nas faixas locais de 17h16 a 18h59 e estritamente após 19h foi de 2.528.064, acima de 2,5 milhões. Na alternativa doméstica em Brasília, foi de 2.531.432. A contagem se refere a todos os eleitores dessas seções. Não foi possível extrair dela 2,5 milhões de votos individuais após o horário, nem atribuir irregularidade jurídica a cada encerramento.',('R1','R4','D01','D05'))
add('B09BAS B09BAP','Bahia: 936 seções e 72,31% para Lula','Os dois números conferem incluindo exatamente 19h00',
'No corte estrito, posterior a 19:00:00, foram encontradas 933 seções e 72,329212% dos votos válidos para Lula, arredondados para 72,33%. A tabela de horários já produzida contém outras três seções exatamente às 19:00:00. Incluindo essas três, o grupo passa a 936 seções e 72,312850%, que arredondam para 72,31%. Portanto, os dois números do original são reproduzíveis no critério inclusivo, a partir de 19h00. A legenda “após 19h” não distingue esses dois cortes.',('R1',))
add('B09PES B09PEP','Pernambuco: 657 seções e 65,70% para Lula','Os dois números conferem',
'Foram reproduzidas 657 seções com encerramento local estritamente posterior a 19:00:00. A votação de Lula no grupo foi de 65,695616% dos votos válidos, que arredondam para 65,70%. Trata-se da votação total dessas seções, sem determinar em que horário cada voto foi registrado.',('R1',))
add('B09MAP','Maranhão: 83,31% para Lula','O percentual confere',
'O percentual calculado no grupo com encerramento local estritamente posterior a 19:00:00 foi de 83,306581%, que arredonda para 83,31%. O original não informa a quantidade de seções nessa linha; por isso, não há uma quantidade alegada a comparar. O resultado descreve o grupo, não o horário individual dos votos.',('R1',))
add('B09SPS B09SPP','São Paulo: 1.571 seções e 57,46% para Lula','Os dois números conferem incluindo exatamente 19h00',
'No corte local estritamente posterior a 19:00:00, foram encontradas 1.567 seções e 57,458821% dos votos válidos para Lula, arredondados para 57,46%. Existem outras quatro seções exatamente às 19:00:00 na tabela já produzida. Incluindo essas quatro, são 1.571 seções e 57,457326%, também arredondados para 57,46%. Assim, a linha original é reproduzível no critério inclusivo, a partir de 19h00.',('R1',))
add('B10','Contraste das seções tardias com o restante de São Paulo','O contraste descritivo confere',
'Usando o grupo inclusivo que reproduz as 1.571 seções, Lula teve 57,46% dos válidos. Por diferença entre os totais estaduais e os totais desse grupo, nas demais 102.085 seções sua participação foi de aproximadamente 45,98%. Portanto, o contraste com o restante de São Paulo é real como descrição agregada. A subtração usa somente os totais já tabulados. Ela não controla a composição geográfica dos grupos nem determina a causa da diferença.',('R1',))
add('C05','Liberação mediante simples digitação do ano de nascimento','Procedimento existe; descrição é incompleta',
'As fontes oficiais consultadas descrevem uma identificação alternativa que pode envolver o ano de nascimento, mas também conferência de documento, caderno e procedimentos do mesário. Assim, a presença dessa alternativa é confirmada; descrevê-la como apenas digitar um ano omite outras etapas. Não foram observados individualmente os procedimentos realizados em cada mesa.',('D02','D03'))
add('C01 C02','8.632.488 habilitações e 6,73%','Os dois números conferem',
'O total foi de 8.632.488 habilitações biográficas, equivalentes a 6,731716% do comparecimento nacional, arredondados para 6,73%. O detalhamento biométrico usado está disponível para 497.897 seções domésticas; as 1.310 seções do exterior sem esse detalhamento não foram imputadas como zero. O percentual de 6,73% usa o comparecimento nacional, como no original; limitado ao comparecimento das seções com detalhe, seria aproximadamente 6,75%. O campo deve ser distinguido da categoria separada de pessoas sem biometria cadastrada, que somou 7.251.810. Habilitação biográfica também não é uma identificação individual do candidato escolhido pelo eleitor.',('R1','R6','D02','D03'))
add('C03','Margem final de 4.430.191 votos','O número confere',
'A reconstrução resultou em 64.256.232 votos para Lula e 59.826.041 para Flávio Bolsonaro, com diferença de 4.430.191. O total de cada candidato fechou com a totalização oficial nas reconciliações realizadas. Brancos e nulos não integram essa margem de votos válidos.',('R1','R3'))
add('C04','Liberações equivalentes a quase o dobro da margem','A razão aproximada confere',
'A razão entre 8.632.488 habilitações biográficas e a margem de 4.430.191 é de 1,948559, ou cerca de 1,95 vez. A expressão “quase o dobro” é compatível com essa razão aproximada; não é uma igualdade exata com 2. A divisão não informa quantas habilitações foram indevidas nem para quem essas pessoas votaram.',('R1',))
add('C06','Correlação entre habilitação manual e votação de Lula','Resultado próprio disponível; cálculo do autor não verificável',
'O original não apresenta coeficiente, gráfico, população ou código para conferir seu teste específico. Na análise já concluída desta auditoria, a correlação bruta de Pearson foi positiva e fraca, aproximadamente 0,068. Nos modelos com controles geográficos e de características das seções, a associação positiva não permaneceu clara: com controle municipal, o intervalo de 95% incluiu zero. Isso não apaga a associação descritiva bruta, mas limita a afirmação de uma relação positiva persistente ou causal.',('R7',))

add('D05','Distribuição gaussiana dos percentuais','A premissa não foi demonstrada',
'Não há no original uma demonstração de que os percentuais por seção deveriam seguir uma curva normal. Percentuais são limitados entre 0 e 100 e dependem de tamanhos de seção e diferenças geográficas. As distribuições de referência já calculadas nesta auditoria foram binomial e beta-binomial, sob hipóteses explícitas. Nenhuma dessas distribuições funciona como uma regra que toda votação legítima precisa obrigatoriamente seguir.',('R8',))
add('D01L D01B D03','Unanimidade: 106, quatro e razão de 26,5 para um','Os três números conferem',
'Na base completa, houve 106 seções com 100% dos votos válidos para Lula e quatro para Flávio. A razão foi exatamente 26,5 para um. Seções sem votos válidos não foram classificadas como unânimes. Nas simulações já realizadas, o modelo beta-binomial não reproduziu bem o extremo de Lula: sua mediana foi de duas seções unânimes, diante de 106 observadas. Isso indica inadequação desse modelo para explicar integralmente a cauda observada; não identifica, sozinho, a causa da concentração. O modelo incluiu 499.130 seções, enquanto as contagens nacionais aqui apresentadas usam a base completa.',('R1','R6','R8'))
add('D02L D02B D04','Mais de 90%: 6.899, 384 e razão de 18 para um','Os totais citados correspondem a 90% ou mais',
'Com o critério estrito de mais de 90%, os totais foram 6.816 seções para Lula e 378 para Flávio. Com o critério de 90% ou mais, foram 6.899 e 384, exatamente os números da tabela original. Portanto, a tabela usa números reproduzíveis, mas sua legenda não descreve o limite que os reproduz. A razão é aproximadamente 18 para um nos dois critérios: cerca de 18,03 no estrito e 17,97 no inclusivo.',('R1','R6'))
add('D06','Concentração em áreas rurais com pouca fiscalização','Não foi possível verificar o conjunto da alegação',
'Não foram obtidos uma classificação geográfica específica das seções e um cadastro com a presença efetiva de fiscais partidários. Também não foi demonstrado que as mesmas seções reúnem simultaneamente unanimidade, ruralidade, baixa fiscalização e os maiores índices de habilitação biográfica. Os números de votação e biometria são disponíveis, mas não substituem as duas informações ausentes.',('R1','D14'))
add('E01','Aplicação do primeiro dígito de Benford','Cálculo do autor não verificável; análise própria disponível',
'Não foram fornecidas as saídas ou o código do teste declarado pelo autor. Nos resultados já calculados desta auditoria, o primeiro dígito por seção se afastou de Benford para ambos os candidatos. Por município, Lula apresentou compatibilidade com a referência de primeiro dígito e Flávio apresentou desvio; no segundo dígito municipal, ambos apresentaram compatibilidade. A alteração com a escala de agregação precisa ser considerada. Não foi demonstrado que a aplicação de Benford a essas contagens, por si, permite identificar manipulação.',('R9',))
add('E02','Ausência dos gráficos de Benford e correlação','A ausência nos sete prints confere',
'Os sete prints não incluem os gráficos mencionados. Isso permite confirmar a nota de ausência, mas não permite concluir se o autor produziu ou deixou de produzir os gráficos em outro arquivo. Nenhum valor de teste ausente foi inventado para completar a resposta.',('R0',))
add('G01','Decisão sobre passaportes sete minutos após a proclamação','Não foi possível conferir os sete minutos nem a ordem dos protocolos',
'Não foram obtidos em conjunto a decisão assinada com sua marca de tempo, o instante verificável da proclamação e os protocolos dos recursos. A nota da Polícia Federal menciona a PET 16877/DF, mas não fornece essas marcas temporais. Assim, não foi possível confirmar o intervalo de sete minutos nem que o ato antecedeu todos os recursos citados.',('D06','D11'))
add('G02','Articulação de prisão cautelar pela Polícia Federal','Não foi possível confirmar a articulação descrita',
'A nota oficial disponível relata representação por cautelares de viagem e contatos. Ela não comprova a articulação informal de prisão com base em boatos descrita nos prints. Seriam necessários os autos e documentos que identificassem o pedido, seu fundamento e os atos efetivamente praticados. O conteúdo limitado da nota não é usado para afirmar que nenhum outro fato ocorreu.',('D06','D11'))
add('G03','Saída do país sob proteção diplomática dos Estados Unidos','Não foi possível confirmar a proteção e o nexo causal',
'Não foi obtida documentação primária suficiente que confirme proteção diplomática dos Estados Unidos ou vincule uma saída do país à articulação mencionada no ponto anterior. Entrada, residência, asilo e proteção diplomática são situações diferentes e não foram tratadas como equivalentes.',('D06','D07','D11'))
add('G05','Coincidência com apurações financeiras e abafamento','Não foi possível confirmar a relação proposta',
'O documento não fornece uma cronologia documental suficiente para conferir todas as datas e relacionar os atos a uma operação de abafamento. Mesmo uma coincidência de semana não estabelece a motivação dos agentes. A existência dos acontecimentos, seus horários e o vínculo causal exigem evidências separadas.',('R0','D06','D11'))
add('G04','Montante de quarenta milhões de dólares','Não foi possível verificar o valor',
'Não foram obtidos documentos financeiros primários que confirmem o montante de US$ 40 milhões, sua moeda, datas, origem e destino. A frase continua na página 5 do original. O valor não foi tratado como confirmado nem como falso: permanece sem verificação documental suficiente.',('R0',))

add('G04C','Destinação do montante à família de magistrados','Não foi possível confirmar os repasses alegados',
'Esta passagem completa a frase dos US$ 40 milhões da página anterior. Não foram obtidos contratos, comprovantes bancários, decisões ou outros documentos primários suficientes para identificar beneficiários, natureza e valor dos repasses descritos. Por esse motivo, a alegação não pôde ser verificada.',('R0',))
add('G06','Declaração atribuída a Donald Trump','Há registro jornalístico; fala integral não conferida',
'Foi localizado relato da Associated Press que atribui a Trump uma alegação de manipulação eleitoral. Não foi obtida a íntegra primária da declaração para conferir todos os termos, inclusive a ligação específica com a prorrogação. A existência de uma declaração e a demonstração factual do que ela afirma são verificações diferentes.',('D10',))
add('G07','Acolhimento da oposição pela Argentina','Não foi possível conferir o sentido amplo da frase',
'A frase não define se “acolheu” significa entrada, residência, asilo ou outra proteção. Na coletiva oficial de 27 de outubro, o porta-voz argentino informou não haver pedido de asilo naquele momento. Isso não resolve a situação migratória posterior nem comprova ou refuta, sozinho, todas as possíveis acepções de acolhimento.',('D07',))
add('G08','Publicação chinesa associando prorrogação e resultado','A publicação dessa interpretação foi localizada',
'A Xinhua publicou em 26 de outubro uma interpretação que relaciona a extensão da votação ao aumento de votos de Lula. Portanto, foi localizado registro desse teor. Em 27 de outubro, a mesma agência também reproduziu o levantamento de aproximadamente 34 mil votos tardios e a margem superior a 4,43 milhões. As duas publicações devem ser consideradas. A existência da interpretação jornalística não calcula quantos votos seriam diferentes sem a prorrogação.',('D08','D09'))
add('H06','Maior auditoria de microdados eleitorais já realizada no Brasil','Não foi possível verificar o superlativo',
'Não foi apresentado um inventário comparativo de auditorias, com critérios de tamanho, cobertura e profundidade. O número de seções declarado pode ser conferido, mas não basta para estabelecer que o trabalho foi o maior já realizado. Esse superlativo permanece não verificado.',('R0','R1'))
add('H01','Vitória de Flávio até 17h','Confere para um grupo de seções; não para um placar individual nesse instante',
'Foi reproduzida a vantagem de Flávio no grupo de seções cujo encerramento local ocorreu até 17:00:59. Esse recorte não separa todos os votos do país registrados antes das 17h, porque exclui os votos anteriores a esse instante nas seções que encerraram mais tarde. Não foi possível determinar o placar individual nacional às 17h a partir desse agrupamento.',('R1','R4','R5'))
add('H02','Virada exclusivamente nas seções após o prazo legal','Saldo dos grupos disponível; qualificação jurídica e causal não confirmada',
'O grupo de encerramento local a partir de 17:01:00 apresentou saldo de 6.177.738 votos para Lula, enquanto o grupo anterior apresentou saldo de 1.747.639 para Flávio. Esses grupos não representam a ordem em que os votos foram depositados ou totalizados. Também não se pode classificar cada encerramento tardio como fora do prazo legal apenas por seu horário. A formulação integral não foi confirmada por esse recorte.',('R1','R4','D01','D05'))
add('H05','8,6 milhões sem validação biométrica, quase o dobro da margem','Os números e a razão aproximada conferem',
'O total exato de habilitações biográficas foi de 8.632.488 e a margem entre candidatos foi de 4.430.191: razão de aproximadamente 1,95 vez. Esse volume não foi identificado como um conjunto de votos exclusivamente de Lula, nem como 8,6 milhões de eleitores sem identificação documental. A contagem não equivale a uma quantidade de votos comprovadamente indevidos.',('R1','R6','D02','D03'))
add('H03','Milhões de votos computados à noite e percentuais acima de 70%','Há grupos com esses totais e percentuais; horário individual não demonstrado',
'Os comparecimentos dos grupos de encerramento tardio superam milhões em alguns recortes, e foram reproduzidos percentuais superiores a 70% para Lula em grupos da Bahia e do Maranhão. Isso se refere à votação de todo o dia nessas seções. Os logs temporais reconciliados identificaram 33.995 registros após 17h, com cobertura parcial. Não foi estabelecido um total de milhões de votos individuais registrados à noite.',('R1','R4','R5'))
add('F03','Repetição da alegação de sonegação por 72 horas','Não foi possível confirmar a duração e a atribuição de intenção',
'Permanece a limitação descrita na página 2: não há histórico completo e independente de disponibilidade de cada produto e URL. A duração de 72 horas não foi fechada. A palavra “sonegados” ainda atribui uma intenção, que também não foi demonstrada pela simples leitura de datas atuais do catálogo.',('D12','D13'))
add('H04','Falta de integridade matemática, quebra de protocolos e mudança judicial das regras','Resultados numéricos disponíveis; acusação composta não confirmada',
'Na parte aritmética, os RDVs das 499.207 seções coincidiram com os BUs e as 261 reconciliações nacionais/estaduais com a totalização não tiveram divergências. Isso contrasta com uma afirmação genérica de falta de integridade matemática, embora não certifique todo o procedimento eleitoral. Já a identificação indevida de eleitores, o descumprimento de protocolos e a extensão jurídica dos atos exigem documentos e ocorrências específicos. Não foi possível confirmar esse conjunto de acusações com as evidências reunidas.',('R3','R5','D01','D02','D05'))
add('X08','Arquivos salvos e gráficos traçados pelo autor','Não foi possível verificar os arquivos particulares',
'Os arquivos e gráficos desta auditoria foram preservados, mas isso não comprova a organização dos arquivos particulares do autor dos prints. Não houve acesso ao código, aos logs de execução ou aos gráficos originais declarados. A afirmação sobre o material particular do autor permanece não verificável com o que foi fornecido.',('R0',),
'Os arquivos estão salvos, os gráficos estão traçados',5)

add('I01','Escopo declarado: sem hackers, satélites ou adulteração de código','A declaração consta no original; execução não verificável',
'O original declara explicitamente esse limite de escopo. É possível confirmar que a declaração está nos prints. Não é possível verificar todas as atividades efetivamente realizadas pelo autor sem seus arquivos de trabalho. Essa declaração, por si, não confirma nem refuta as demais conclusões do documento.',('R0',))
add('I04','Substituição do controle digital pela habilitação manual','Existe alternativa de identificação; utilização indevida não quantificada',
'As fontes consultadas descrevem procedimentos alternativos à identificação biométrica e os arquivos registram habilitações biográficas. O número de 8.632.488 foi reproduzido. A existência dessa alternativa não informa quantas liberações, se alguma, ocorreram de forma indevida. Não foi obtida uma contagem nacional documentada de ocorrências individuais que permitisse medir esse uso indevido.',('R1','R6','D02','D03'))
add('X06','Exploração em escala inédita no segundo turno','Não foi possível verificar a comparação histórica',
'“Inédita” exige comparar o procedimento e seus volumes com eleições anteriores, com definições equivalentes. As comparações de 2022 já concluídas neste projeto são de votação presidencial; elas não medem historicamente todas as habilitações biográficas ou ocorrências de identificação indevida. Portanto, não foi possível confirmar uma escala histórica inédita de exploração.',('R0','R11'),
'foi explorada em escala inédita no segundo turno',6)
add('I02','Quatro falhas de biometria e uso do ano de nascimento','Alternativa descrita; quatro tentativas sem confirmação própria',
'A documentação consultada descreve tentativas de reconhecimento e identificação alternativa com outras conferências além do ano de nascimento. Não foi possível confirmar aqui o limite exato de quatro tentativas na íntegra normativa preservada; esse detalhe fica sem verificação própria nesta entrega. As saídas agregadas também não reconstituem quantas tentativas foram feitas para cada pessoa. O volume de habilitações é mensurável; a formulação de que bastaria apenas digitar o ano não descreve integralmente os controles documentados.',('D02','D03'))
add('I03','Controle social nas seções urbanas com fiscais','Não foi possível conferir a comparação urbano/rural',
'Não foi obtido cadastro de presença e atuação efetiva dos fiscais por seção. Tampouco foi medida a realização de testemunhos ou conferências em cada local. Por esse motivo, não foi possível confirmar que o procedimento alternativo recebeu um tipo de controle nas áreas urbanas e outro nas áreas rurais.',('D14',))
add('A06','Verificação de todos os hashes SHA-512 pelo autor','Hashes oficiais conferidos aqui; procedimento do autor não verificável',
'Os pacotes BWeb e de correspondências usados nesta auditoria coincidiram com os SHA-512 oficiais disponíveis. Nos pacotes brutos de arquivos transmitidos, hash do pacote, hash de membro e assinatura foram registrados como verificações distintas; os hashes do BWeb não foram aplicados a arquivos de outro formato. Sem o manifesto e os logs do autor, não foi possível verificar que ele próprio conferiu todos os hashes que declara. O original também diz usar exclusivamente BWeb; não foi possível verificar essa exclusividade do trabalho particular.',('R2','R5','R0'))
add('A03 A03V','Universalidade: todas as seções e 128.236.074 votos','Os totais conferem para a população BWeb',
'Os 499.205 registros de seção no BWeb e 128.236.074 comparecimentos presidenciais foram reproduzidos. A base de BUs tem 499.207 seções, incluindo duas sem votos ausentes do BWeb. Assim, a diferença de duas seções não altera a votação total. A expressão “não fizemos amostragem” descreve o procedimento do autor e não pode ser auditada sem seus arquivos de execução.',('R1','R2','R3'))
add('X07','Cruzamento dos três campos oficiais','Os campos e a possibilidade de cruzamento conferem',
'Foram encontrados os campos QT_ELEI_BIOM_SEM_HABILITACAO, DT_ENCERRAMENTO e QT_VOTOS nos esquemas examinados. Eles permitem relacionar métricas no nível da seção, respeitando cargo, turno e candidato. Métricas repetidas por candidato precisam ser deduplicadas antes de somar eleitores. A existência dos campos não transforma o horário de encerramento em horário individual do voto, nem identifica o candidato escolhido por uma pessoa habilitada biograficamente.',('R2','R12'),
'A quantidade de eleitores habilitados sem validação biométrica (QT_ELEI_BIOM_SEM_HABILITACAO); o horário físico de encerramento gravado pela urna eletrônica (DT_ENCERRAMENTO); e a votação nominal conferida a cada candidato na respectiva seção (QT_VOTOS).',6)

add('J01','Repetição dos 8.632.488 liberados manualmente','O total confere como habilitação biográfica',
'O resultado foi de 8.632.488 habilitações biográficas. A razão para a margem final é aproximadamente 1,95 vez, compatível com a aproximação “quase duas vezes”. Essa razão aritmética não mede uma “margem de segurança” definida do sistema e não quantifica identificação indevida. Também não associa esses eleitores individualmente a um candidato.',('R1','R6'))
add('J02','Repetição da margem de 4.430.191 votos','O número confere',
'Os totais reconstruídos de 64.256.232 votos para Lula e 59.826.041 para Flávio resultam na diferença de 4.430.191. Essa margem corresponde aos votos válidos, sem brancos ou nulos.',('R3',))
add('J03','Seções com mais de 95% de identificação biométrica e equilíbrio','Resultados disponíveis; equilíbrio não foi definido',
'Na saída já calculada, 45.435 seções tinham taxa de habilitação biométrica superior a 95% do comparecimento presidencial. Somaram 5.428.190 votos para Lula e 5.871.495 para Flávio: 48,04% e 51,96% dos válidos, respectivamente. O original não define quanto de diferença ainda considera “equilíbrio”; por isso, são apresentados os números, sem impor retrospectivamente uma margem de aceitação. Esse grupo não representa todos os eleitores biométricos do país.',('R10',))
add('J04','Faixas de 20%, 30% e mais de 50% de liberação e patamar de 61%','Crescimento por faixas e patamar de 61% aparecem; reta não foi demonstrada',
'A tabela já produzida mostra crescimento do percentual agregado de Lula conforme aumentam as faixas de habilitação biográfica. Nas faixas acima de 20% até 30%, acima de 30% até 50% e acima de 50%, as participações calculadas a partir dos votos agregados foram de aproximadamente 58,09%, 59,12% e 61,20%. Portanto, o patamar superior a 61% aparece nesse agrupamento. “Em linha reta” não foi estabelecido, nem se demonstrou causalidade. O último grupo contém 97 seções, enquanto o primeiro desses três contém 3.686; os grupos têm tamanhos muito diferentes. A tabela completa e os controles geográficos são apresentados após as respostas.',('R7',))
add('J05','Coincidência entre noite, habilitação biográfica e menos fiscais','Não foi possível verificar a combinação completa',
'Horário de encerramento e habilitação biográfica são variáveis disponíveis, mas não foi obtida medição da presença de fiscais. Os resultados reunidos não permitem confirmar que o mesmo conjunto de seções combina todas as condições da frase. Também não basta uma coincidência municipal para afirmar que as mesmas seções ou pessoas apresentam todas elas. O componente sobre fiscalização permanece não verificado.',('R1','R4','R7','D14'))
add('J06','Desarme das travas em milhões de votos','Volume de habilitações conhecido; desarme irregular não demonstrado',
'O volume de habilitações biográficas é de 8.632.488. Os registros não as classificam automaticamente como liberações indevidas, pessoas não identificadas ou votos de um candidato. Não foi obtida uma quantidade documentada de ocorrências individuais que demonstrasse desarme irregular das travas na escala afirmada. A frase reúne uma contagem reproduzível e uma descrição de irregularidade que não foi possível confirmar.',('R1','R6','D02','D03'))
add('J07','Documento não constitui laudo judicial','A ressalva consta nos prints',
'A frase está expressamente presente no original. Essa conferência não estabelece a identidade, qualificação profissional, autoria ou eventual utilização posterior do documento em um processo. O novo relatório também se limita à conferência das informações e das evidências identificadas.',('R0',))

